#!/usr/bin/env bash
set +e
ADM="$(docker exec nyv-gateway printenv DATABASE_URL_ADMIN 2>/dev/null)"; ADM="${ADM%\"}"; ADM="${ADM#\"}"
ADM="$(echo "$ADM" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/')"
APP="$(docker exec nyv-gateway printenv DATABASE_URL 2>/dev/null)"; APP="${APP%\"}"; APP="${APP#\"}"
APP="$(echo "$APP" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/')"
SQL="$(echo '' | base64 -d)"
echo "=== apply policy as nyvadmin ==="
docker run --rm --network host -e PGURL="$ADM" -e SQL="$SQL" postgres:16-alpine sh -c 'psql "$PGURL" -v ON_ERROR_STOP=1 -c "$SQL"' 2>&1 | tail -8
echo "=== TEST: insert as nv_app WITHOUT tenant GUCs (was failing pre-fix) ==="
docker run --rm --network host -e PGURL="$APP" postgres:16-alpine sh -c 'psql "$PGURL" -v ON_ERROR_STOP=1 -c "INSERT INTO public.sdk_api_request_logs (application_id, api_key_id, request_id, endpoint, method, status_code, latency_ms, tokens_in, tokens_out, metadata) VALUES (1, 1, '"'"'audit-fix-probe-001'"'"', '"'"'/__audit_probe'"'"', '"'"'GET'"'"', 200, 5, 0, 0, '"'"'{\"probe\":true}'"'"'::jsonb);"' 2>&1
echo "=== confirm row visible to admin + cleanup ==="
docker run --rm --network host -e PGURL="$ADM" postgres:16-alpine sh -c 'psql "$PGURL" -At -F "|" -c "SELECT '"'"'probe_row'"'"', request_id, endpoint, status_code FROM public.sdk_api_request_logs WHERE request_id='"'"'audit-fix-probe-001'"'"'; DELETE FROM public.sdk_api_request_logs WHERE request_id='"'"'audit-fix-probe-001'"'"'; SELECT '"'"'cleanup_done'"'"';"' 2>&1
